#!/bin/sh
# Tests the classi-staging files of the private-photo steps A and B (supabase/staging/*private_photos*.sql, generated by
# scripts/staging/gen_private_photos_files.py) on throwaway LOCAL databases that look like classi-staging today: every
# migration up to 20261104000000 applied and recorded, and the staging marker. Never touches a hosted database.
# The files only run on the classi-staging cluster id: the test runs copies in which that one constant is replaced by
# this server's cluster id, and checks that nothing else differs. Every check prints PASS: or FAIL:.
# Usage: sh supabase/tests/staging_private_photos_test.sh   (local Postgres, or CI's service via PGSOCK/PGPORT)
set -u
T="$(cd "$(dirname "$0")" && pwd)"; REPO="$(cd "$T/../.." && pwd)"
ST="$REPO/supabase/staging"; A=20261105000000_private_photos; B=20261105010000_private_photos_enforce
STAGING_ID=7702070854497379551
P="psql -h ${PGSOCK:-/var/tmp/pgc} -p ${PGPORT:-54329} -U postgres -q"
W=$(mktemp -d); BASE=ct_pp_base; DB=ct_pp
pass=0; fail=0
ok() { echo "PASS: $1"; pass=$((pass + 1)); }
ko() { echo "FAIL: $1"; fail=$((fail + 1)); }
q() { $P -d "$DB" -Atc "$1"; }
fresh() { $P -c "drop database if exists $DB" -c "create database $DB template $BASE" >/dev/null; }
run() { $P -d "$DB" -v ON_ERROR_STOP=1 -f "$1" > "$W/out" 2>&1; }
# everything the files could change, as one fingerprint
state() { q "select md5(concat_ws('#',
  (select string_agg(format('%s|%s|%s|%s|%s|%s', policyname, cmd, permissive, roles::text, coalesce(qual,'-'), coalesce(with_check,'-')), E'\n' order by policyname) from pg_policies where schemaname='storage' and tablename='objects'),
  (select string_agg(format('%s|%s|%s|%s', p.proname, md5(p.prosrc), coalesce(array_to_string(p.proconfig, ','), '-'), p.prosecdef), E'\n' order by p.proname) from pg_proc p where p.pronamespace='public'::regnamespace),
  (select string_agg(format('%s|%s', tgrelid::regclass, tgname), ',' order by tgrelid::regclass::text, tgname) from pg_trigger where not tgisinternal and tgrelid::regclass::text in ('teachers','institutes','profiles')),
  (select string_agg(format('%s|%s|%s', id, public, coalesce(file_size_limit::text,'-')), ',' order by id) from storage.buckets),
  (select string_agg(table_name||'.'||column_name, ',' order by column_name) from information_schema.columns where table_schema='public' and table_name='profiles'),
  (select string_agg(version, ',' order by version) from supabase_migrations.schema_migrations),
  (select string_agg(key||'='||value, ',' order by key) from public.app_secrets where key in ('deploy_env','private_photos_app')),
  (select string_agg(bucket_id||'/'||name, ',' order by bucket_id, name) from storage.objects),
  (select string_agg(coalesce(pending_changes::text,'-'), ',' order by id) from public.teachers)))"; }
expect_refusal() { # <label> <file> <text>: refused, and nothing at all changed
  before=$(state)
  if run "$2"; then ko "$1: it ran"; return; fi
  grep -q "$3" "$W/out" || { ko "$1: not the expected refusal ($(grep -m1 ERROR "$W/out"))"; return; }
  [ "$(state)" = "$before" ] && ok "$1 (refused, nothing changed)" || ko "$1: refused but the state changed"
}
expect_ok() { if run "$2"; then ok "$1"; else ko "$1: $(grep -m1 ERROR "$W/out")"; fi; }

# ---------- a database like classi-staging today (after P0-1) ----------
$P -c "drop database if exists $BASE" -c "create database $BASE" >/dev/null 2>&1
D="env PGOPTIONS=-cclient_min_messages=warning $P -d $BASE -v ON_ERROR_STOP=1"
$D -f "$T/supabase_stub.sql" >/dev/null
$D -c "create schema if not exists supabase_migrations; create table if not exists supabase_migrations.schema_migrations (version text primary key, name text, statements text[])" >/dev/null
for f in "$REPO"/supabase/migrations/*.sql; do
  v=$(basename "$f" | cut -d_ -f1); [ "$v" \> 20261104000000 ] && break
  $D -f "$f" >/dev/null || { echo "FAIL: base: $f did not apply"; exit 1; }
  $D -c "insert into supabase_migrations.schema_migrations (version, name) values ('$v', '$(basename "$f" .sql | cut -d_ -f2-)')" >/dev/null
done
$D -c "insert into public.app_secrets (key, value) values ('deploy_env', 'staging') on conflict (key) do update set value = excluded.value" >/dev/null
$D -c "insert into auth.users (id, email) values ('75000000-0000-0000-0000-00000000000a','a@t'), ('75000000-0000-0000-0000-00000000000b','b@t'), ('75000000-0000-0000-0000-00000000000c','adm@t')" >/dev/null
$D -c "update public.profiles set roles = array['admin']::app_role[] where id = '75000000-0000-0000-0000-00000000000c'" >/dev/null
$D -c "insert into public.teachers (user_id, name, town) values ('75000000-0000-0000-0000-00000000000a', 'معلم اختبار', 'باقة')" >/dev/null
DB=$BASE; BASE_STATE=$(state); DB=ct_pp
LOCAL_ID=$($P -d $BASE -Atc "select system_identifier from pg_control_system()")

# ---------- the files ----------
(cd "$REPO" && PGSOCK=${PGSOCK:-/var/tmp/pgc} PGPORT=${PGPORT:-54329} python3 scripts/staging/gen_private_photos_files.py --check > "$W/gen" 2>&1) \
  && ok "the staging files are exactly what the generator makes from the committed migrations" || ko "staging files are stale: $(cat "$W/gen")"
for f in apply_$A rollback_$A apply_$B rollback_$B mark_private_photos_app_deployed unmark_private_photos_app_deployed; do
  [ "$(grep -c "$STAGING_ID" "$ST/$f.sql")" = 1 ] || ko "$f: cluster id count"
  sed "s/$STAGING_ID/$LOCAL_ID/" "$ST/$f.sql" > "$W/$f.sql"
  [ "$(diff "$ST/$f.sql" "$W/$f.sql" | grep -c '^[<>]')" = 2 ] && ok "$f: the test copy differs only in the cluster id line" || ko "$f: test copy differs in more"
  grep -qE '^\\(i|ir|include)' "$ST/$f.sql" && ko "$f includes another file" || true
done
for m in $A $B; do
  awk '/^-- ===== BEGIN MIGRATION/{f=1;next}/^-- ===== END MIGRATION/{f=0}f' "$ST/apply_$m.sql" | cmp -s - "$REPO/supabase/migrations/$m.sql" \
    && ok "apply_$m: the embedded migration is the committed file, byte for byte" || ko "apply_$m: embedded migration differs"
  awk '/^-- ===== BEGIN ROLLBACK/{f=1;next}/^-- ===== END ROLLBACK/{f=0}f' "$ST/rollback_$m.sql" > "$W/body"
  grep -v '^--' "$REPO/supabase/rollback/$m.down.sql" | grep -v '^begin;$' | grep -v '^commit;$' | cmp -s - "$W/body" \
    && ok "rollback_$m: the embedded rollback is the committed down file (without its begin/commit)" || ko "rollback_$m: embedded rollback differs"
done

# ---------- apply A: refusals (fresh copy each time; nothing may change) ----------
fresh; expect_refusal "A outside classi-staging (the committed file)" "$ST/apply_$A.sql" "refusing: not the classi-staging database"
fresh; q "delete from public.app_secrets where key='deploy_env'" >/dev/null; expect_refusal "A without the staging marker" "$W/apply_$A.sql" "not marked staging"
fresh; q "insert into supabase_migrations.schema_migrations (version) values ('20261105010000')" >/dev/null; expect_refusal "A with a newer migration recorded" "$W/apply_$A.sql" "newest recorded migration is not 20261104000000"
fresh; q "insert into supabase_migrations.schema_migrations (version) values ('20261105000000')" >/dev/null; expect_refusal "A already recorded" "$W/apply_$A.sql" "already recorded"
fresh; q "delete from supabase_migrations.schema_migrations where version='20261104000000'" >/dev/null; expect_refusal "A before P0-1" "$W/apply_$A.sql" "newest recorded migration is not 20261104000000"
fresh; q "create policy \"x\" on storage.objects for select to authenticated using (true)" >/dev/null; expect_refusal "A with an extra storage policy" "$W/apply_$A.sql" "policies on storage.objects are not the expected state"
fresh; q "drop policy \"avatars: read own\" on storage.objects; create policy \"avatars: read\" on storage.objects for select using (bucket_id = 'avatars')" >/dev/null; expect_refusal "A with the old public read policy (P0-1 not in place)" "$W/apply_$A.sql" "policies on storage.objects are not the expected state"
fresh; q "alter function public.admin_review(text, uuid, boolean, text) set search_path = public, extensions" >/dev/null; expect_refusal "A when admin_review differs from the expected one" "$W/apply_$A.sql" "photo functions"
fresh; q "grant execute on function public.admin_review(text, uuid, boolean, text) to anon" >/dev/null; expect_refusal "A when execute rights differ" "$W/apply_$A.sql" "photo functions"
fresh; q "alter table storage.objects disable row level security" >/dev/null; expect_refusal "A when RLS is off" "$W/apply_$A.sql" "row level security is off"
fresh; $P -c "alter role authenticated bypassrls" >/dev/null; expect_refusal "A when authenticated bypasses RLS" "$W/apply_$A.sql" "bypasses row level security"; $P -c "alter role authenticated nobypassrls" >/dev/null
fresh; q "update storage.buckets set public = false where id = 'avatars'" >/dev/null; expect_refusal "A when the photos bucket is not public" "$W/apply_$A.sql" "storage buckets are not the expected state"
fresh; q "insert into storage.buckets (id, name, public) values ('photos-private', 'photos-private', true)" >/dev/null; expect_refusal "A when a public bucket photos-private already exists" "$W/apply_$A.sql" "storage buckets are not the expected state"
fresh; q "update public.teachers set pending_changes = '{\"photo_path\": \"x\"}'" >/dev/null; expect_refusal "A with a waiting private photo already present" "$W/apply_$A.sql" "waiting private photo"
sed '/^do \$check\$/,/^end \$check\$;/ s/\$exp\$admin_publish_photo|/$exp$BROKEN|/' "$W/apply_$A.sql" > "$W/apply_A_bad.sql"
grep -q 'exp\$BROKEN|' "$W/apply_A_bad.sql" || ko "test setup: the broken copy of apply A was not made"
fresh; expect_refusal "A whose result check fails is rolled back completely" "$W/apply_A_bad.sql" "aborting: the photo functions"

# ---------- apply A: success, and what it allows ----------
fresh; expect_ok "A runs on a database like classi-staging" "$W/apply_$A.sql"
[ "$(q "select max(version) || ' ' || count(*) filter (where version = '20261105000000') from supabase_migrations.schema_migrations")" = "20261105000000 1" ] && ok "A is recorded once, as the newest" || ko "A record"
[ "$(q "select count(*) from pg_policies where schemaname='storage' and tablename='objects' and policyname like 'avatars: %own'")" = 4 ] && ok "the four P0-1 policies are still there" || ko "P0-1 policies"
as() { q "set role authenticated; set request.jwt.claim.sub = '75000000-0000-0000-0000-00000000000$1'; $2"; }
as a "insert into storage.objects (bucket_id, name) values ('photos-private', '75000000-0000-0000-0000-00000000000a/pending/teacher-t1-aaaaaaaa.jpg'), ('photos-private', '75000000-0000-0000-0000-00000000000a/profile-t1-bbbbbbbb.jpg')" >/dev/null 2>&1 \
  && ok "the owner uploads a waiting photo and a profile photo to the private bucket" || ko "owner upload"
[ "$(as b "select count(*) from storage.objects where bucket_id='photos-private'")" = 0 ] && ok "another user sees none of them" || ko "other user sees private files"
[ "$(q "set role anon; select count(*) from storage.objects where bucket_id='photos-private'")" = 0 ] && ok "a visitor sees none of them" || ko "visitor sees private files"
[ "$(as c "select string_agg(name, ',') from storage.objects where bucket_id='photos-private'")" = "75000000-0000-0000-0000-00000000000a/pending/teacher-t1-aaaaaaaa.jpg" ] && ok "the admin sees the waiting photo only, never the profile photo" || ko "admin visibility"
as b "insert into storage.objects (bucket_id, name) values ('photos-private', '75000000-0000-0000-0000-00000000000a/profile-t2-cccccccc.jpg')" >/dev/null 2>&1 && ko "B uploads into A's private folder" || ok "another user cannot upload into the owner's private folder"
after_a=$(state)

# ---------- rollback A: refusals ----------
expect_refusal "rollback A outside classi-staging (the committed file)" "$ST/rollback_$A.sql" "refusing: not the classi-staging database"
expect_refusal "rollback A with private files present" "$W/rollback_$A.sql" "photos-private still holds files"
q "delete from storage.objects where bucket_id='photos-private'" >/dev/null
q "update public.profiles set avatar_path = '75000000-0000-0000-0000-00000000000a/profile-t1-bbbbbbbb.jpg' where id = '75000000-0000-0000-0000-00000000000a'" >/dev/null
expect_refusal "rollback A with a private profile photo in use" "$W/rollback_$A.sql" "private profile photos are in use"
q "update public.profiles set avatar_path = null" >/dev/null
q "update public.teachers set pending_changes = '{\"photo_path\": \"x\"}'" >/dev/null
expect_refusal "rollback A with a waiting private photo" "$W/rollback_$A.sql" "waiting private photos exist"
q "update public.teachers set pending_changes = null where pending_changes ? 'photo_path'" >/dev/null
q "insert into supabase_migrations.schema_migrations (version) values ('20261105010000')" >/dev/null
expect_refusal "rollback A with step B recorded" "$W/rollback_$A.sql" "newest recorded migration is not 20261105000000"
q "delete from supabase_migrations.schema_migrations where version='20261105010000'" >/dev/null
q "create policy \"x\" on storage.objects for select to authenticated using (true)" >/dev/null
expect_refusal "rollback A with an unexpected policy" "$W/rollback_$A.sql" "policies on storage.objects are not the expected state"
q "drop policy \"x\" on storage.objects" >/dev/null
sed '/^do \$check\$/,/^end \$check\$;/ s/\$exp\$admin_review|/$exp$BROKEN|/' "$W/rollback_$A.sql" > "$W/rollback_A_bad.sql"
grep -q 'exp\$BROKEN|' "$W/rollback_A_bad.sql" || ko "test setup: the broken copy of rollback A was not made"
expect_refusal "rollback A whose result check fails is rolled back completely" "$W/rollback_A_bad.sql" "aborting: the photo functions"

# ---------- rollback A: success, then a second cycle ----------
expect_ok "rollback A runs" "$W/rollback_$A.sql"
[ "$(q "select max(version) from supabase_migrations.schema_migrations")" = 20261104000000 ] && ok "after rollback A the newest migration is 20261104000000 again" || ko "record after rollback A"
[ "$(q "select count(*) from pg_proc where proname in ('submit_photo','admin_publish_photo','profile_insert_review')")" = 0 ] && ok "the step-A functions are gone" || ko "functions left"
[ "$(q "select (select count(*) from storage.buckets where id='photos-private') || ' ' || (select count(*) from information_schema.columns where table_name='profiles' and column_name='avatar_path')")" = "1 1" ] \
  && ok "kept on purpose: the empty private bucket and the unused avatar_path column" || ko "kept objects"
expect_ok "A applies again after its rollback (kept bucket and column accepted)" "$W/apply_$A.sql"
expect_ok "and rolls back again" "$W/rollback_$A.sql"

# ---------- B: refusals, the marker, success, rollback ----------
fresh; expect_ok "(setup) A applied" "$W/apply_$A.sql"
expect_refusal "B without the 'app deployed' marker" "$W/apply_$B.sql" "not marked as deployed"
expect_refusal "the marker outside classi-staging" "$ST/mark_private_photos_app_deployed.sql" "refusing: not the classi-staging database"
expect_ok "the marker is set on staging after A" "$W/mark_private_photos_app_deployed.sql"
expect_refusal "B outside classi-staging" "$ST/apply_$B.sql" "refusing: not the classi-staging database"
q "create policy \"x\" on storage.objects for select to authenticated using (true)" >/dev/null
expect_refusal "B with an unexpected policy" "$W/apply_$B.sql" "policies on storage.objects are not the expected state"
q "drop policy \"x\" on storage.objects" >/dev/null
expect_ok "B runs after A and the marker" "$W/apply_$B.sql"
[ "$(q "select max(version) from supabase_migrations.schema_migrations")" = 20261105010000 ] && ok "B is the newest migration" || ko "B record"
as a "insert into storage.objects (bucket_id, name) values ('avatars', '75000000-0000-0000-0000-00000000000a/teacher.jpg')" >/dev/null 2>&1 && ko "after B a user still uploads to the public bucket" || ok "after B a user can no longer upload to the public bucket"
expect_refusal "the marker cannot be removed while B is recorded" "$W/unmark_private_photos_app_deployed.sql" "step B is recorded"
expect_refusal "rollback A while B is recorded" "$W/rollback_$A.sql" "newest recorded migration is not 20261105000000"
expect_refusal "rollback B outside classi-staging" "$ST/rollback_$B.sql" "refusing: not the classi-staging database"
expect_ok "rollback B runs" "$W/rollback_$B.sql"
as a "insert into storage.objects (bucket_id, name) values ('avatars', '75000000-0000-0000-0000-00000000000a/teacher.jpg')" >/dev/null 2>&1 && ok "after rollback B users upload to their public folder again" || ko "upload after rollback B"
q "delete from storage.objects where name = '75000000-0000-0000-0000-00000000000a/teacher.jpg'" >/dev/null
expect_ok "the marker is removed after rollback B" "$W/unmark_private_photos_app_deployed.sql"
expect_ok "rollback A after rollback B" "$W/rollback_$A.sql"
DB=$BASE; base_pol=$(q "select string_agg(policyname, ',' order by policyname) from pg_policies where schemaname='storage'"); DB=ct_pp
[ "$(q "select string_agg(policyname, ',' order by policyname) from pg_policies where schemaname='storage'")" = "$base_pol" ] \
  && [ "$(q "select max(version) from supabase_migrations.schema_migrations")" = 20261104000000 ] \
  && [ "$(q "select count(*) from public.app_secrets where key = 'private_photos_app'")" = 0 ] \
  && ok "A, marker, B, rollback B, unmark, rollback A: back to the state before A (plus the kept bucket and column)" || ko "full cycle: policies [$(q "select string_agg(policyname, ',' order by policyname) from pg_policies where schemaname='storage'")] vs [$base_pol], newest $(q "select max(version) from supabase_migrations.schema_migrations"), marker $(q "select count(*) from public.app_secrets where key = 'private_photos_app'")"

$P -c "drop database if exists $DB" -c "drop database if exists $BASE" >/dev/null 2>&1; rm -rf "$W"
echo "staging private photos files: $pass passed, $fail failed"
[ "$fail" = 0 ]
